<?php
declare(strict_types=1);
require_once __DIR__ . '/../../config/app.php';
requireLogin();
requireRole([ROLE_CUSTOMER]);

$orderId=(int)($_GET['order_id'] ?? 0); $userId=(int)$_SESSION['user_id'];
$stmt=$conn->prepare("SELECT o.*,hr.restaurant_name,hr.address AS restaurant_address,hr.phone AS restaurant_phone FROM orders o JOIN halal_restaurants hr ON hr.id=o.restaurant_id WHERE o.id=? AND o.customer_id=? AND o.payment_status='paid' AND o.payment_verified_at IS NOT NULL AND o.receipt_number IS NOT NULL AND EXISTS (SELECT 1 FROM billing_payment_requests b WHERE b.order_id=o.id AND b.provider='paymongo' AND b.service_type='order' AND b.status='paid') LIMIT 1");
$stmt->bind_param('ii',$orderId,$userId); $stmt->execute(); $order=$stmt->get_result()->fetch_assoc(); $stmt->close();
if (!$order) { http_response_code(404); exit('A verified paid order receipt was not found.'); }
$items=json_decode((string)$order['items_json'],true); if (!is_array($items)) $items=[];
$money=static fn($amount) => 'PHP '.number_format((float)$amount,2);
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Receipt <?= htmlspecialchars($order['receipt_number']) ?></title><style>body{font-family:Arial,sans-serif;color:#172033;margin:0;background:#f3f4f6}.receipt{width:760px;max-width:calc(100% - 32px);margin:32px auto;background:#fff;padding:36px;box-sizing:border-box;box-shadow:0 2px 12px rgba(0,0,0,.08)}h1{margin:0;color:#065f46;font-size:28px}.muted{color:#667085}table{width:100%;border-collapse:collapse;margin-top:22px}th,td{padding:10px 4px;border-bottom:1px solid #e5e7eb;text-align:left}th:last-child,td:last-child{text-align:right}.totals{margin-left:auto;width:320px;max-width:100%;margin-top:20px}.total{font-size:18px;font-weight:700;border-top:2px solid #111827;padding-top:10px}@media print{body{background:#fff}.receipt{box-shadow:none;margin:0;max-width:none;width:100%}.no-print{display:none}}</style></head><body><main class="receipt"><div style="display:flex;justify-content:space-between;gap:24px"><div><h1><?= htmlspecialchars($order['restaurant_name']) ?></h1><div class="muted"><?= nl2br(htmlspecialchars((string)($order['restaurant_address'] ?? ''))) ?><br><?= htmlspecialchars((string)($order['restaurant_phone'] ?? '')) ?></div></div><div style="text-align:right"><strong>PAYMENT RECEIPT</strong><br><span class="muted">Receipt <?= htmlspecialchars($order['receipt_number']) ?><br>Issued <?= htmlspecialchars((string)$order['receipt_issued_at']) ?></span></div></div><hr style="border:0;border-top:1px solid #e5e7eb;margin:22px 0"><p><strong>Order:</strong> <?= htmlspecialchars($order['order_number']) ?><br><strong>Payment method:</strong> <?= htmlspecialchars(ucwords(str_replace('_',' ',(string)$order['payment_method']))) ?><br><strong>Payment status:</strong> Verified paid</p><table><thead><tr><th>Item</th><th>Qty</th><th>Amount</th></tr></thead><tbody><?php foreach($items as $item): $qty=max(1,(int)($item['qty']??1)); $price=(float)($item['price']??0); ?><tr><td><?= htmlspecialchars((string)($item['name']??'Item')) ?></td><td><?= $qty ?></td><td><?= $money($price*$qty) ?></td></tr><?php endforeach; ?></tbody></table><div class="totals"><div style="display:flex;justify-content:space-between"><span>Subtotal</span><span><?= $money($order['subtotal']) ?></span></div><?php if((float)($order['discount_amount']??0)>0): ?><div style="display:flex;justify-content:space-between"><span>Discount</span><span>-<?= $money($order['discount_amount']) ?></span></div><?php endif; ?><?php if((float)$order['delivery_fee']>0): ?><div style="display:flex;justify-content:space-between"><span>Delivery fee</span><span><?= $money($order['delivery_fee']) ?></span></div><?php endif; ?><?php if((float)($order['platform_fee']??0)>0): ?><div style="display:flex;justify-content:space-between"><span>Halal Keeps platform fee</span><span><?= $money($order['platform_fee']) ?></span></div><?php endif; ?><div class="total" style="display:flex;justify-content:space-between"><span>Total paid</span><span><?= $money($order['total_amount']) ?></span></div></div><p class="muted" style="margin-top:28px;font-size:12px">This receipt is issued after PayMongo webhook verification. Keep the receipt number for support enquiries.</p><p class="no-print"><button onclick="window.print()">Print receipt</button> <a href="<?= BASE_URL ?>dashboard/customer/orders.php">Back to orders</a></p></main></body></html>
